drop index if exists public.tour_manager_prediction_group_once_idx;
alter table public.tour_manager_daily_prediction_games drop column selection_group;
alter table public.tour_manager_daily_prediction_games add column selection_group text generated always as (
 case when station_key='2026-w39-seoul-singapore' then event_key
 when station_key in ('2026-w46-wta-finals','2026-w47-atp-finals') then tour||':'||game_slot::text else tour end) stored;
create unique index tour_manager_prediction_group_once_idx on public.tour_manager_daily_prediction_games(station_key,contest_date,selection_group);
create or replace function public.tour_manager_take_atp_finals_opening_notice()
returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid(); inserted uuid;
begin
 if u is null then raise exception 'authentication_required';end if;
 if now() >= timestamptz '2026-11-15 21:00:00+08'
 or not exists(select 1 from public.tour_manager_station_configs where station_key='2026-w47-atp-finals' and season=2026) then return null;end if;
 insert into public.tour_manager_opening_notice_receipts(user_id,notice_key)
 values(u,'atp_finals_2026_opening') on conflict do nothing returning user_id into inserted;
 if inserted is null then return null;end if;
 return jsonb_build_object('message','经纪人ATP年终开售！累计收益前八免费，最高毛收益可达16500；普通用户最高毛收益可达11200，快来选购吧。');
end;
$$;
revoke all on function public.tour_manager_take_atp_finals_opening_notice() from public,anon;
grant execute on function public.tour_manager_take_atp_finals_opening_notice() to authenticated;

